import java.io.*;
import java.net.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.Base64;

/**
 * Legacy order processing endpoint - receives serialized OrderRequest objects
 * from internal microservices for batch processing.
 * 
 * NOTE: This endpoint uses Java native serialization for backward compatibility
 * with OrderService v2.x clients that haven't migrated to JSON yet.
 * Migration tracked in JIRA-4521.
 */
public class OrderBatchServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;
    private static final int MAX_PAYLOAD_SIZE = 10 * 1024 * 1024; // 10MB

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String contentType = request.getContentType();
        String authHeader = request.getHeader("X-Internal-Service-Key");

        // Validate internal service key
        if (authHeader == null || !validateServiceKey(authHeader)) {
            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            response.getWriter().write("{\"error\": \"Invalid service key\"}");
            return;
        }

        if (contentType != null && contentType.contains("application/x-java-serialized-object")) {
            handleSerializedPayload(request, response);
        } else if (contentType != null && contentType.contains("application/json")) {
            handleJsonPayload(request, response);
        } else {
            response.setStatus(HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE);
            response.getWriter().write("{\"error\": \"Unsupported content type\"}");
        }
    }

    private void handleSerializedPayload(HttpServletRequest request, 
                                          HttpServletResponse response) throws IOException {
        try {
            // Read the serialized object from request body
            InputStream inputStream = request.getInputStream();
            byte[] data = readStream(inputStream, MAX_PAYLOAD_SIZE);

            if (data.length == 0) {
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                return;
            }

            // Check for base64 encoding (some clients send b64)
            String dataStr = new String(data, "UTF-8");
            byte[] objectBytes;
            if (isBase64(dataStr.trim())) {
                objectBytes = Base64.getDecoder().decode(dataStr.trim());
            } else {
                objectBytes = data;
            }

            // Deserialize the order request
            ByteArrayInputStream bais = new ByteArrayInputStream(objectBytes);
            ObjectInputStream ois = new ObjectInputStream(bais);
            Object obj = ois.readObject(); // VULNERABLE: no class filtering
            ois.close();

            if (obj instanceof OrderRequest) {
                OrderRequest order = (OrderRequest) obj;
                processOrder(order);
                response.setStatus(HttpServletResponse.SC_OK);
                response.getWriter().write("{\"status\": \"processed\", \"orderId\": \"" 
                    + order.getOrderId() + "\"}");
            } else {
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                response.getWriter().write("{\"error\": \"Expected OrderRequest object\"}");
            }
        } catch (ClassNotFoundException e) {
            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            response.getWriter().write("{\"error\": \"Deserialization failed\"}");
        }
    }

    private void handleJsonPayload(HttpServletRequest request,
                                    HttpServletResponse response) throws IOException {
        // JSON path uses Jackson - safe from deserialization attacks
        response.setStatus(HttpServletResponse.SC_OK);
        response.getWriter().write("{\"status\": \"json_processed\"}");
    }

    private boolean validateServiceKey(String key) {
        // Keys are rotated monthly via AWS Secrets Manager
        String expectedKey = System.getenv("INTERNAL_SERVICE_KEY");
        return expectedKey != null && expectedKey.equals(key);
    }

    private boolean isBase64(String s) {
        return s.matches("^[A-Za-z0-9+/\\r\\n]+=*$") && s.length() % 4 == 0;
    }

    private byte[] readStream(InputStream is, int maxSize) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] chunk = new byte[8192];
        int bytesRead;
        int totalRead = 0;
        while ((bytesRead = is.read(chunk)) != -1) {
            totalRead += bytesRead;
            if (totalRead > maxSize) throw new IOException("Payload too large");
            buffer.write(chunk, 0, bytesRead);
        }
        return buffer.toByteArray();
    }

    private void processOrder(OrderRequest order) {
        // Business logic - writes to RDS
    }
}

class OrderRequest implements Serializable {
    private static final long serialVersionUID = 2L;
    private String orderId;
    private String customerId;
    private double amount;

    public String getOrderId() { return orderId; }
    public String getCustomerId() { return customerId; }
    public double getAmount() { return amount; }
}
